import { ref, computed, type Ref, type ComputedRef } from 'vue';
import { useI18n } from 'vue-i18n';
import { ApiChat } from '@/api/api-chat';
import { useConversationStore } from '@/store/modules/conversation';
import { useUserStore } from '@/store/modules/user';
import { debounce, formatRelativeTimeFromUtc, isWithinDaysFromUtc } from '@/utils/util';
import { showMessageSuccess, showMessageError } from '@/utils/ui-feedback';

// 类型定义
interface Conversation {
    id: string | number;
    title: string;
    created_at: string;
    time?: string; // 格式化的时间显示
    [key: string]: any;
}

interface ConversationGroup {
    label: string;
    type?: string;
    conversations: Conversation[];
}

interface ApiResponse<T> {
    data: {
        items: T[];
        has_more: boolean;
    };
    code: number;
}

interface UseConversationDataOptions {
    enableMobileFeatures?: boolean; // 是否启用移动端特性
}

interface UseConversationDataReturn {
    // 响应式数据
    conversations: Ref<Conversation[]>;
    loading: Ref<boolean>;
    hasMore: Ref<boolean>;
    lastId: Ref<string | number>;
    searchText: Ref<string>;
    errorMessage: Ref<string>;
    showPreloader: Ref<boolean>;
    currentConversation: Ref<Conversation | null>;
    
    // 计算属性
    isLoggedIn: ComputedRef<boolean>;
    currentConversationId: ComputedRef<string | number | null>;
    filteredConversations: ComputedRef<Conversation[]>;
    conversationList: ComputedRef<Conversation[]>;
    groupedConversations: ComputedRef<ConversationGroup[]>;
    
    // 方法
    loadData: (reset?: boolean) => Promise<void>;
    initializeData: () => Promise<void>;
    resetState: () => void;
    refreshData: () => Promise<void>;
    retryLoad: () => Promise<void>;
    setCurrentConversationStatus: (conversation: Conversation) => void;
    renameConversation: (conversation: Conversation, newTitle: string) => Promise<boolean>;
    deleteConversations: (conversationIds: (string | number)[]) => Promise<boolean>;
    debouncedSearch: (searchValue: string) => void;
    debouncedLoadMore: () => void;
    executeSearch: (searchValue: string) => Promise<void>;
}

export function useConversationData(options: UseConversationDataOptions = {}): UseConversationDataReturn {
    const { enableMobileFeatures = false } = options;
    const { t } = useI18n();
    const conversationStore = useConversationStore();
    const userStore = useUserStore();
    
    // 响应式数据
    const PAGE_SIZE: number = 20;
    const lastId: Ref<string | number> = ref<string | number>(0);
    const hasMore: Ref<boolean> = ref<boolean>(true);
    const loading: Ref<boolean> = ref<boolean>(false);
    const conversations: Ref<Conversation[]> = ref<Conversation[]>([]);
    const searchText: Ref<string> = ref<string>('');
    const errorMessage: Ref<string> = ref<string>('');
    const showPreloader: Ref<boolean> = ref<boolean>(false);
    const currentConversation: Ref<Conversation | null> = ref<Conversation | null>(null);

    // 计算属性
    const isLoggedIn: ComputedRef<boolean> = computed(() => userStore.isLoggedIn);
    const currentConversationId: ComputedRef<string | number | null> = computed(() => 
        conversationStore.getCurrentConversationId
    );

    // 搜索过滤后的对话列表
    const filteredConversations: ComputedRef<Conversation[]> = computed(() => {
        if (!searchText.value) return conversations.value;
        return conversations.value.filter(c =>
            c.title.toLowerCase().includes(searchText.value.toLowerCase())
        );
    });

    // 添加时间显示的对话列表
    const conversationList: ComputedRef<Conversation[]> = computed(() => {
        return filteredConversations.value.map(c => ({
            ...c,
            time: formatRelativeTimeFromUtc(c.created_at)
        }));
    });

    // 按时间分组的对话列表（移动端特性）- 参考桌面端分组逻辑
    const groupedConversations: ComputedRef<ConversationGroup[]> = computed(() => {
        if (!enableMobileFeatures) return [];
        
        // 为每个会话添加格式化的时间，使用UTC时间处理函数
        const conversationsWithTime = filteredConversations.value.map(c => ({
            ...c,
            time: formatRelativeTimeFromUtc(c.created_at)
        }));

        // 分组函数 - 与桌面端保持一致
        const groupConversations = (conversations: Conversation[]) => {
            const today: Conversation[] = [];
            const yesterday: Conversation[] = [];
            const lastWeek: Conversation[] = [];
            const thisYear: Conversation[] = [];

            conversations.forEach(c => {
                // 使用UTC时间处理函数检查时间范围
                if (isWithinDaysFromUtc(c.created_at, 1)) {
                    // 24小时内
                    today.push(c);
                } else if (isWithinDaysFromUtc(c.created_at, 2) && !isWithinDaysFromUtc(c.created_at, 1)) {
                    // 1-2天内（昨天）
                    yesterday.push(c);
                } else if (isWithinDaysFromUtc(c.created_at, 7) && !isWithinDaysFromUtc(c.created_at, 2)) {
                    // 2-7天内
                    lastWeek.push(c);
                } else {
                    // 检查是否在今年
                    try {
                        let utcTime = c.created_at;
                        let timeString = utcTime.trim();

                        if (!/[+-]\d{2}:?\d{2}|Z$/i.test(timeString)) {
                            timeString += 'Z';
                        }

                        const date = new Date(timeString);
                        const now = new Date();
                        const startOfYear = new Date(now.getFullYear(), 0, 1).getTime();

                        if (!isNaN(date.getTime()) && date.getTime() >= startOfYear) {
                            thisYear.push(c);
                        }
                    } catch (error) {
                        console.error('Error processing conversation date:', error);
                        // 出错时放入thisYear分组
                        thisYear.push(c);
                    }
                }
            });

            // 返回非空的分组
            const groups: ConversationGroup[] = [];
            if (today.length > 0) {
                groups.push({ type: 'today', label: t('today'), conversations: today });
            }
            if (yesterday.length > 0) {
                groups.push({ type: 'yesterday', label: t('yesterday'), conversations: yesterday });
            }
            if (lastWeek.length > 0) {
                groups.push({ type: 'lastWeek', label: t('lastWeek'), conversations: lastWeek });
            }
            if (thisYear.length > 0) {
                groups.push({ type: 'thisYear', label: t('thisYear'), conversations: thisYear });
            }

            return groups;
        };

        return groupConversations(conversationsWithTime);
    });

    // 防抖搜索函数（移动端特性）
    const debouncedSearch = debounce((searchValue: string) => {
        executeSearch(searchValue);
    }, 300);

    // 防抖加载更多函数（移动端特性）
    const debouncedLoadMore = debounce(() => {
        if (hasMore.value && !loading.value) {
            loadData(false);
        }
    }, 100);

    // 加载会话列表数据
    const loadData = async (reset: boolean = false): Promise<void> => {
        if (loading.value || (!hasMore.value && !reset)) return;
        
        loading.value = true;
        errorMessage.value = ''; // 清除之前的错误
        
        try {
            if (reset) {
                lastId.value = 0;
                hasMore.value = true;
            }
            
            const res: ApiResponse<Conversation> = await ApiChat.getChatHistory(PAGE_SIZE, lastId.value);
            const list: Conversation[] = res.data.items || [];
            
            // 判断是否请求过会话历史接口，如果请求过，则不覆盖原有数据
            const shouldOverride: boolean = reset || !conversationStore.hasLoadedHistory;

            if (shouldOverride) {
                // 首次加载、重置或强制重新加载时，覆盖原有数据
                conversations.value = list;
                conversationStore.setConversations(list);
                conversationStore.setHasLoadedHistory(true);
            } else {
                conversations.value = [...conversations.value, ...list];
                conversationStore.appendConversations(list);
            }
            
            hasMore.value = res.data.has_more;
            if (list && Array.isArray(list) && list.length > 0) {
                lastId.value = list[list.length - 1].id;
            }
            
            conversationStore.setPageInfo(lastId.value, hasMore.value);
        } catch (error: any) {
            console.error('Failed to load conversation data:', error);
            
            // 设置用户友好的错误信息
            if (error.code === 401) {
                errorMessage.value = t('authExpired');
            } else if (error.code === 403) {
                errorMessage.value = t('accessDenied');
            } else if (error.message && error.message.includes('network')) {
                errorMessage.value = t('networkError');
            } else {
                errorMessage.value = t('loadFailed');
            }
            
            hasMore.value = false;
        } finally {
            loading.value = false;
            showPreloader.value = false; // 隐藏预加载指示器
            
            // 加载完成后设置当前会话状态
            const currentConv = conversationStore.currentConversation;
            if (currentConv) {
                setCurrentConversationStatus(currentConv);
            }
        }
    };

    // 搜索执行（移动端特性）
    const executeSearch = async (searchValue: string): Promise<void> => {
        if (!searchValue || searchValue.trim() === '') {
            return;
        }
        // 这里可以添加服务器端搜索逻辑
        // 目前使用前端过滤，在计算属性 filteredConversations 中处理
    };

    // 刷新数据（移动端特性）
    const refreshData = async (): Promise<void> => {
        if (loading.value) return;

        errorMessage.value = '';
        showPreloader.value = false;

        try {
            await loadData(true);
        } catch (error) {
            errorMessage.value = t('refreshFailed');
        } finally {
        }
    };

    // 重试加载（移动端特性）
    const retryLoad = async (): Promise<void> => {
        errorMessage.value = '';
        await loadData(true);
    };

    // 设置当前会话状态
    const setCurrentConversationStatus = (conversation: Conversation): void => {
        currentConversation.value = conversation;
        conversationStore.setCurrentConversationId(conversation.id);
    };

    // 重命名会话（移动端特性）
    const renameConversation = async (conversation: Conversation, newTitle: string): Promise<boolean> => {
        if (!conversation || !newTitle.trim()) return false;

        const originalTitle = conversation.title;

        try {
            // 先更新本地UI
            const conv = conversations.value.find(c => c.id === conversation.id);
            if (conv) {
                conv.title = newTitle.trim();
            }

            const res = await ApiChat.updateSession({
                id: Number(conversation.id),
                update: { title: newTitle.trim() }
            });

            if (res.code === 200) {
                conversationStore.updateConversationTitle(conversation.id, newTitle.trim());
                showMessageSuccess(res.message || t('renameSuccess'));
                return true;
            } else {
                // 恢复原标题
                if (conv) {
                    conv.title = originalTitle;
                }
                showMessageError(t('renameFailed'));
                return false;
            }
        } catch (error) {
            console.error('Rename conversation error:', error);
            // 恢复原标题
            const conv = conversations.value.find(c => c.id === conversation.id);
            if (conv) {
                conv.title = originalTitle;
            }
            showMessageError(t('renameFailed'));
            return false;
        }
    };

    // 删除会话（移动端特性）
    const deleteConversations = async (conversationIds: (string | number)[]): Promise<boolean> => {
        if (!conversationIds.length) return false;

        try {
            const deletePromises = conversationIds.map(id =>
                ApiChat.deleteSession(Number(id))
            );

            await Promise.all(deletePromises);

            // 检查删除的会话中是否包含当前选中的会话
            conversationIds.forEach(id => {
                if (currentConversation.value?.id === id) {
                    currentConversation.value = null;
                    conversationStore.setCurrentConversationId(null);
                }
            });

            // 从本地数据中移除
            conversations.value = conversations.value.filter(
                c => !conversationIds.includes(c.id)
            );

            // 更新store
            conversationIds.forEach(id => {
                conversationStore.deleteConversation(id);
            });
            return true;
        } catch (error) {
            console.error('Delete conversations error:', error);
            showMessageError(t('deleteFailed'));
            // 删除失败时重新加载数据
            loadData(true);
            return false;
        }
    };

    // 初始化数据
    const initializeData = async (): Promise<void> => {
        // 只有在用户已登录时才加载会话历史
        if (!userStore.isLoggedIn) {
            console.log('用户未登录，跳过会话历史加载');
            return;
        }

        // 检查是否已加载过会话历史
        if (conversationStore.hasLoadedHistory) {
            const storeConversations: Conversation[] = conversationStore.conversations;
            if (storeConversations.length > 0) {
                conversations.value = storeConversations;
                lastId.value = conversationStore.lastId;
                hasMore.value = conversationStore.hasMore;
                console.log(`从缓存加载${conversations.value.length}条会话记录`);
                return;
            }
        }

        // 未加载过会话历史，主动请求接口
        console.log('首次加载会话历史');
        await loadData(true);
    };

    // 重置状态
    const resetState = (): void => {
        conversations.value = [];
        lastId.value = 0;
        hasMore.value = true;
        loading.value = false;
        searchText.value = '';
        errorMessage.value = '';
        showPreloader.value = false;
        currentConversation.value = null;
    };

    return {
        // 响应式数据
        conversations,
        loading,
        hasMore,
        lastId,
        searchText,
        errorMessage,
        showPreloader,
        currentConversation,
        
        // 计算属性
        isLoggedIn,
        currentConversationId,
        filteredConversations,
        conversationList,
        groupedConversations,
        
        // 方法
        loadData,
        initializeData,
        resetState,
        refreshData,
        retryLoad,
        setCurrentConversationStatus,
        renameConversation,
        deleteConversations,
        debouncedSearch: debouncedSearch as (searchValue: string) => void,
        debouncedLoadMore: debouncedLoadMore as () => void,
        executeSearch
    };
} 